using Microsoft.EntityFrameworkCore; using Axpense.Api.Domain; namespace Axpense.Api.Data;
public class AxpenseDbContext(DbContextOptions<AxpenseDbContext> options):DbContext(options){public DbSet<Organization> Organizations=>Set<Organization>();public DbSet<User> Users=>Set<User>();public DbSet<Vehicle> Vehicles=>Set<Vehicle>();public DbSet<MaintenanceRecord> MaintenanceRecords=>Set<MaintenanceRecord>();public DbSet<Expense> Expenses=>Set<Expense>();public DbSet<FuelTransaction> FuelTransactions=>Set<FuelTransaction>();public DbSet<Budget> Budgets=>Set<Budget>();public DbSet<Driver> Drivers=>Set<Driver>();public DbSet<VehicleAssignment> VehicleAssignments=>Set<VehicleAssignment>();protected override void OnModelCreating(ModelBuilder m){m.Entity<Organization>().HasKey(x=>x.Id);m.Entity<User>().HasKey(x=>x.Id);m.Entity<Vehicle>().HasKey(x=>x.Id);m.Entity<MaintenanceRecord>().HasKey(x=>x.Id);m.Entity<Expense>().HasKey(x=>x.Id);m.Entity<FuelTransaction>().HasKey(x=>x.Id);m.Entity<Budget>().HasKey(x=>x.Id);m.Entity<Driver>().HasKey(x=>x.Id);m.Entity<VehicleAssignment>().HasKey(x=>x.Id);m.Entity<User>().HasIndex(x=>new{x.OrganizationId,x.Email}).IsUnique();m.Entity<Vehicle>().HasIndex(x=>new{x.OrganizationId,x.PlateNumber}).IsUnique();m.Entity<MaintenanceRecord>().HasIndex(x=>new{x.OrganizationId,x.DueDate});m.Entity<MaintenanceRecord>().HasOne(x=>x.Vehicle).WithMany().HasForeignKey(x=>x.VehicleId).OnDelete(DeleteBehavior.Cascade);m.Entity<Expense>().HasIndex(x=>new{x.OrganizationId,x.ExpenseDate});m.Entity<FuelTransaction>().HasIndex(x=>new{x.OrganizationId,x.TransactionDate});m.Entity<Budget>().HasIndex(x=>new{x.OrganizationId,x.Year,x.Month,x.Category});m.Entity<Driver>().HasIndex(x=>new{x.OrganizationId,x.FullName});m.Entity<VehicleAssignment>().HasIndex(x=>new{x.OrganizationId,x.VehicleId,x.StartDate});m.Entity<VehicleAssignment>().HasOne(x=>x.Vehicle).WithMany().HasForeignKey(x=>x.VehicleId).OnDelete(DeleteBehavior.Cascade);m.Entity<VehicleAssignment>().HasOne(x=>x.Driver).WithMany().HasForeignKey(x=>x.DriverId).OnDelete(DeleteBehavior.Cascade);m.Entity<Expense>().HasOne(x=>x.Vehicle).WithMany().HasForeignKey(x=>x.VehicleId).OnDelete(DeleteBehavior.SetNull);m.Entity<FuelTransaction>().HasOne(x=>x.Vehicle).WithMany().HasForeignKey(x=>x.VehicleId).OnDelete(DeleteBehavior.Cascade);m.Entity<Organization>().HasMany(x=>x.Users).WithOne(x=>x.Organization).HasForeignKey(x=>x.OrganizationId);m.Entity<Organization>().HasMany(x=>x.Vehicles).WithOne(x=>x.Organization).HasForeignKey(x=>x.OrganizationId);}}
